function fillRandom(buffer) {
  let from = 0
  while (from < buffer.length) {
    let to = Math.min(from + GET_RANDOM_LIMIT, buffer.length)
    crypto.getRandomValues(buffer.subarray(from, to))
    from = to
  }
}

export function random(bytes) {
  // `|=` convert `bytes` to number to prevent `valueOf` abusing
  bytes |= 0
  if (bytes < 0) throw new RangeError('Wrong ID size')
  // `random()` is used rarely and not in hot paths, so it makes
  // a direct crypto call instead of using a byte pool.
  let buffer = Buffer.allocUnsafe(bytes)
  fillRandom(buffer)
  return buffer
}

import { urlAlphabet } from './url-alphabet/index.js'

export { urlAlphabet }

// `crypto.getRandomValues` rejects requests over 65536 bytes,
// so bigger buffers are filled by chunks.
const GET_RANDOM_LIMIT = 65536

export let nanoid = (size = 21) => {
  let id = ''
  let bytes = crypto.getRandomValues(new Uint8Array((size |= 0)))
  while (size--) {
    // The following mask reduces the random byte in the 0-255 value
    // range to the 0-63 value range.
    id += urlAlphabet[bytes[size] & 63]
  }
  return id
}

test(`recovers from crypto errors`, () => {
  nanoid(1)
  let original = crypto.getRandomValues
  crypto.getRandomValues = () => {
    throw new Error('Entropy failure')
  }
  try {
    throws(() => {
      nanoid(65536)
    }, /Entropy failure/)
    throws(() => {
      random(131072)
    }, /Entropy failure/)
  } finally {
    crypto.getRandomValues = original
  }
  equal(nanoid().length, 21)
  equal(random(10).length, 10)
})

getRandomValues(array) {
  for (let i = 0; i < array.length; i++) {
    array[i] = Math.floor(Math.random() * 256)
  }
  return array
}

### مُولِّد بايتات عشوائية مخصّص

تتيح لك `customRandom` إنشاء `nanoid` واستبدال الأبجدية
ومُولِّد البايتات العشوائية الافتراضي.

في هذا المثال، يتم استخدام مُولِّد مبني على بذرة (seed):

</div>

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

